mapper.select:
SELECT c.id,v.card_kind AS kind,v.title,c.status,c.revision,v.id AS version_id,
  v.version_number,v.source_count,v.related_concept_count,c.updated_at
FROM memory_card c JOIN memory_card_version v
  ON v.owner_id=c.owner_id AND v.card_id=c.id AND v.id=c.current_version_id
WHERE c.owner_id=#{owner} AND c.status=#{status}
AND v.card_kind=#{kind}
AND v.title LIKE #{pattern} ESCAPE '!'

  AND EXISTS (SELECT 1 FROM memory_card_source s WHERE s.owner_id=c.owner_id
    AND s.card_id=c.id AND s.version_id=v.id AND s.knowledge_item_id=#{sourceItemId})


  AND EXISTS (SELECT 1 FROM memory_card_concept r WHERE r.owner_id=c.owner_id
    AND r.card_id=c.id AND r.version_id=v.id AND r.concept_id=#{relatedConceptId})

AND c.id > #{cursor}
ORDER BY c.id LIMIT #{limit}

SELECT id,version_number AS number,card_kind AS kind,title,created_at
FROM memory_card_version WHERE owner_id=#{owner} AND card_id=#{id}
AND version_number < #{before}
ORDER BY version_number DESC LIMIT #{limit}

mapper.update:
UPDATE memory_card SET current_version_id=#{versionId},version_number=#{number},revision=revision+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{id} AND revision=#{expected} AND status='ACTIVE'
  AND revision < 1000 AND version_number < 1000

UPDATE memory_card SET status=#{status},revision=revision+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{id} AND revision=#{expected} AND revision < 1000
  AND status <> #{status}
